import { TableVariantConfig } from './shared-table-types.js';
import { ThresholdExtended } from '../../core/types/threshold-types.js';
/** Serializable configuration object for showing and hiding columns. */
export type ColumnVisibilityConfig = {
    [column: string]: 'visible' | 'hidden';
};
/**
 * Pagination config
 */
export interface TablePaginationConfig {
    pageSize?: number;
    pageIndex?: number;
}
/**
 * Shareable props of DataTable that can be imported/exported
 */
export interface DataTableContextConfig {
    /**
     * Default state column visibility.
     */
    columnVisibility?: ColumnVisibilityConfig;
    /**
     * Enables DataTable to use the full width of its container.
     * @defaultValue false
     */
    fullWidth?: boolean;
    /**
     * Enables line breaking (breaking long text in multiple lines) for all column cells in the table.
     * When set to `true` content of the cell is wrapped,
     * when set to `false` content is truncated.
     * @defaultValue false
     */
    lineWrap?: boolean;
    /**
     * Enables resizing for all columns within the table.
     * @defaultValue false
     */
    resizable?: boolean;
    /**
     * Enables row selection. Adds an extra column with appropriate checkboxes.
     *
     * @defaultValue false
     */
    selectableRows?: boolean;
    /**
     * Configures the thresholds used for the rows highlighting.
     */
    rowThresholds?: ThresholdExtended[];
    /**
     * Enables sorting for all columns which do not have it explicitly
     * disabled with the `disableSortBy` prop on the column entry.
     * @defaultValue false
     */
    sortable?: boolean;
    /**
     * Select props of pagination can be exported or imported
     */
    pagination?: TablePaginationConfig;
    /**
     * Configures the visual look of DataTable.
     * @defaultValue 'default'
     */
    variant?: TableVariantConfig | 'default';
}
/**
 *  Config type, holding all the required config used in the DataTable.
 */
export type RequiredDataTableConfiguration = Required<DataTableContextConfig>;
